insert into public.categories (slug, title, summary, family, used_for, examples, source_url, image_url, focus, sort, status) values ('connectors', 'Connectors', 'The core of the range: BNC, UHF, SMA, F, XLR, M12, solar and power connectors.', array['BNC', 'UHF', 'SMA', 'F', 'XLR', 'M12', 'Solar', 'Power / SB series', 'LED wall power', 'Computer power']::text[], array['Joining and terminating signal and power lines', 'Panel-mounted inlets and outlets', 'Replacement parts for existing wiring']::text[], array['BNC Connector Screw Type Nickel Tag', 'BNC Panel Type', 'Computer Male Fuse + Switch Panel Mounting']::text[], 'https://setmiindia.com/product-category/connectors/', '/products/bnc.png', '50% 95%', 0, 'published') on conflict (slug) do nothing;
insert into public.categories (slug, title, summary, family, used_for, examples, source_url, image_url, focus, sort, status) values ('circular-connectors', 'Circular Connectors', 'Round multi-pin connectors in sizes from 12mm to 40mm.', array['12mm', '16mm', '20mm', '25mm', '30mm', '35mm', '40mm']::text[], array['Multi-pin cable-to-cable and panel connections']::text[], array['17mm 5 Pin Waterproof Extension Circular Male Connector', '21mm 4 Pin Waterproof Extension Circular Connector']::text[], 'https://setmiindia.com/product-category/circular-connectors/', '/products/circular.png', '50% 96%', 1, 'published') on conflict (slug) do nothing;
insert into public.categories (slug, title, summary, family, used_for, examples, source_url, image_url, focus, sort, status) values ('waterproof-connectors', 'Waterproof Connectors', '13mm, 17mm and 21mm circular connectors listed with an IP67 rating on the product pages.', array['13mm', '17mm', '21mm', 'Male / Female', 'Extension']::text[], array['Connections that must stay sealed against moisture']::text[], array['13mm 2 Pin Waterproof Circular Male Connector', '13mm 3 Pin Waterproof Circular Female Connector']::text[], 'https://setmiindia.com/product-category/waterproof-connectors/', '/products/waterproof.png', '50% 96%', 2, 'published') on conflict (slug) do nothing;
insert into public.categories (slug, title, summary, family, used_for, examples, source_url, image_url, focus, sort, status) values ('couplers', 'Couplers', 'Jointers that link two cables or devices: HDMI, DVI, audio-video and BNC.', array['HDMI', 'DVI', 'Audio Video', 'BNC', 'UHF']::text[], array['Extending an existing cable run', 'Changing cable direction with right-angle jointers']::text[], array['HDMI Jointer', 'HDMI Jointer Right Angle Female To Female', 'HDMI Jointer Panel Mounting Type']::text[], 'https://setmiindia.com/product-category/connectors/couplers/', '/products/couplers.png', '50% 96%', 3, 'published') on conflict (slug) do nothing;
insert into public.categories (slug, title, summary, family, used_for, examples, source_url, image_url, focus, sort, status) values ('sockets-plugs', 'Sockets & Plugs', 'Stereo pins, DC pins and sockets, banana pins and sockets, RJ-45 jointers and Schuko plugs.', array['Stereo pins', 'DC pin & sockets', 'Banana pin & socket', 'RJ-45 jointer', 'Schuko plugs']::text[], array['Audio, DC power and network terminations']::text[], array['Server Connector Female Cable Type', 'Server Connector Male Panel Type']::text[], 'https://setmiindia.com/product-category/connectors/sockets-plugs/', null, null, 4, 'published') on conflict (slug) do nothing;
insert into public.categories (slug, title, summary, family, used_for, examples, source_url, image_url, focus, sort, status) values ('hdmi-splitters', 'HDMI Splitters', 'Splitters that send one HDMI source to several displays, plus related HDMI equipment.', array['2 way', '4 way', '8 way', 'HDMI extender', 'Video capture card']::text[], array['One source to multiple screens']::text[], array['HDMI Splitter 2 Way FJGEAR', 'HDMI Splitter 4 Way FJGEAR', 'HDMI Splitter 8 Way FJGEAR', 'HDMI Extender 200M Sender & Receiver']::text[], 'https://setmiindia.com/hdmi-splitters/', '/products/splitters.png', '50% 90%', 5, 'published') on conflict (slug) do nothing;
insert into public.categories (slug, title, summary, family, used_for, examples, source_url, image_url, focus, sort, status) values ('cables', 'Cables', 'HDMI, DVI, USB, power, computer and audio-video cables.', array['HDMI', 'DVI', 'USB', 'Power', 'Computer', 'Audio-video']::text[], array['Connecting sources, displays, audio equipment and power']::text[], array['2 Pin Computer Cable 1.5 Mtr', '2 RCA to 2 RCA Premium Audio Cable', 'Headphone Y Splitter Cable']::text[], 'https://setmiindia.com/product-category/cables/', '/products/cables.webp', '50% 50%', 6, 'published') on conflict (slug) do nothing;
insert into public.categories (slug, title, summary, family, used_for, examples, source_url, image_url, focus, sort, status) values ('other-products', 'Other Products', 'Clips, multiplugs, switches, terminals and general items, alongside multimedia tweeters and PA horn speakers.', array['Battery clips', 'Multiplugs', 'Switches', 'Terminals', 'Audio-video splitters', 'Tweeters', 'PA horn speakers']::text[], array['Supporting parts for power and audio installations']::text[], array['200 AMP Battery Clip', '50 AMP Battery Clip', '3 Way Multiplug', '12v On Off Toggle Switch']::text[], 'https://setmiindia.com/product-category/other-products/', '/products/other.png', '50% 92%', 7, 'published') on conflict (slug) do nothing;
insert into public.faqs (question, answer, sort, status) select 'What is SETMI INDIA?', 'SETMI INDIA is a Delhi-based supplier of audio-video cables, connectors and multimedia products, serving customers across India since 1983.', 0, 'published' where not exists (select 1 from public.faqs where question = 'What is SETMI INDIA?');
insert into public.faqs (question, answer, sort, status) select 'What products do you offer?', 'Connectors (BNC, UHF, SMA, F, XLR, M12, solar), circular and waterproof connectors, couplers, sockets and plugs, HDMI splitters, cables, and other products such as clips, multiplugs, switches and speakers.', 1, 'published' where not exists (select 1 from public.faqs where question = 'What products do you offer?');
insert into public.faqs (question, answer, sort, status) select 'How can I find the right connector or cable?', 'Browse the categories above, or describe what you are connecting in the enquiry form. Our team will help match it to a product.', 2, 'published' where not exists (select 1 from public.faqs where question = 'How can I find the right connector or cable?');
insert into public.faqs (question, answer, sort, status) select 'Can I enquire about a specific product?', 'Yes. Name the product or paste its link from setmiindia.com into the enquiry form, or message us on WhatsApp.', 3, 'published' where not exists (select 1 from public.faqs where question = 'Can I enquire about a specific product?');
insert into public.faqs (question, answer, sort, status) select 'How do I get a catalogue?', 'The full range is listed on setmiindia.com. If you need something that is not listed, or a specific list, ask through the enquiry form.', 4, 'published' where not exists (select 1 from public.faqs where question = 'How do I get a catalogue?');
insert into public.faqs (question, answer, sort, status) select 'How can I request a quotation?', 'Choose Request a Quotation, pick the product category and tell us the items and quantities you need.', 5, 'published' where not exists (select 1 from public.faqs where question = 'How can I request a quotation?');
insert into public.faqs (question, answer, sort, status) select 'Where can I find product specifications?', 'Specifications are on the individual product pages at setmiindia.com. For anything not listed there, ask our team.', 6, 'published' where not exists (select 1 from public.faqs where question = 'Where can I find product specifications?');
insert into public.faqs (question, answer, sort, status) select 'How can I contact the sales team?', 'Call +91 85868 78111 or +91 11 47414746, WhatsApp +91 85868 78111, or email info@setmiindia.com. We are at 167-168, Old Lajpat Rai Market, opposite Red Fort, Delhi-110006.', 7, 'published' where not exists (select 1 from public.faqs where question = 'How can I contact the sales team?');
